try:
    n_gpu = len(subprocess.run(["nvidia-smi", "-L"], capture_output=True, text=True).stdout.strip().splitlines())
except FileNotFoundError:
    n_gpu = 0
print("检测到 GPU 数量:", n_gpu, "(需要 2 张: 右侧 Settings → Accelerator → GPU T4 x2)")

shutil.rmtree(ROOT / "server", ignore_errors=True)   # 清掉旧版本残留的文件
for rel, b64 in FILES.items():
    p = ROOT / rel
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_bytes(zlib.decompress(base64.b64decode(b64)))
print("已写入 %d 个文件 -> %s" % (len(FILES), ROOT))

if USE_GITHUB:
    tmp = Path("/tmp/gh_clone")
    shutil.rmtree(tmp, ignore_errors=True)
    r = subprocess.run(["git", "clone", "--depth", "1", GITHUB_REPO, str(tmp)])
    if r.returncode == 0:
        for d in ("server", "web", "kaggle"):
            if (tmp / d).exists():
                shutil.copytree(tmp / d, ROOT / d, dirs_exist_ok=True)
        print("已用 GitHub 最新代码覆盖")
    else:
        print("GitHub 拉取失败,继续使用内置代码")

# 在当前进程里运行启动器(这样输出框里能直接显示可点击的网址)
os.chdir(ROOT)
sys.path.insert(0, str(ROOT))
runpy.run_path(str(ROOT / "kaggle" / "run.py"), run_name="__main__")
